Add Features.code:
// Add features to a feature layer. This adaptor has no HTTP helpers,
// so call the ArcGIS REST API with util.request inside fn().
// baseUrl is your org's services host, e.g. https://services.arcgis.com/<orgId>/arcgis
fn(async state => {
  const { baseUrl, token } = state.configuration;
  const features = state.data.submissions.map(s => ({
    geometry: { x: s.longitude, y: s.latitude, spatialReference: { wkid: 4326 } },
    attributes: { site_name: s.siteName, cases: s.caseCount, reported_on: s.date },
  }));
  const res = await util.request(
    'POST',
    `${baseUrl}/rest/services/Cholera_Cases/FeatureServer/0/addFeatures`,
    {
      // ArcGIS expects form-encoded params; `features` is a JSON string.
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ features: JSON.stringify(features), f: 'json', token }).toString(),
    }
  );
  return { ...state, data: res.body };
});

Update Features.code:
// Update features by OBJECTID.
fn(async state => {
  const { baseUrl, token } = state.configuration;
  const features = state.data.updates.map(u => ({
    attributes: { OBJECTID: u.objectId, status: u.status, last_updated: u.date },
  }));
  const res = await util.request(
    'POST',
    `${baseUrl}/rest/services/Health_Facilities/FeatureServer/0/updateFeatures`,
    {
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ features: JSON.stringify(features), f: 'json', token }).toString(),
    }
  );
  return { ...state, data: res.body };
});

Delete Features.code:
// Delete features by OBJECTID (or pass `where` instead).
fn(async state => {
  const { baseUrl, token } = state.configuration;
  const res = await util.request(
    'POST',
    `${baseUrl}/rest/services/Cholera_Cases/FeatureServer/0/deleteFeatures`,
    {
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        objectIds: state.data.objectIds.join(','), // e.g. '1,2,3'
        f: 'json',
        token,
      }).toString(),
    }
  );
  return { ...state, data: res.body };
});

Query Features.code:
// Query features from a feature layer.
fn(async state => {
  const { baseUrl, token } = state.configuration;
  const res = await util.request(
    'GET',
    `${baseUrl}/rest/services/Health_Facilities/FeatureServer/0/query`,
    {
      query: {
        where: `district = '${state.data.district}'`, // SQL-style filter; '1=1' for all
        outFields: '*', // or a comma-separated field list
        returnGeometry: true,
        f: 'json',
        token,
      },
    }
  );
  return { ...state, data: res.body.features };
});

Geocode Address.code:
// Geocode a single-line address.
fn(async state => {
  const res = await util.request(
    'GET',
    'https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates',
    {
      query: {
        SingleLine: state.data.address, // e.g. 'Kenyatta National Hospital, Nairobi'
        outFields: 'Match_addr,Addr_type',
        f: 'json',
        token: state.configuration.token,
      },
    }
  );
  // Best match first: candidates[0].location has x (lon) and y (lat).
  return { ...state, data: res.body.candidates };
});

Generate Token.code:
// Generate an access token and keep it on state for later steps.
fn(async state => {
  const { username, password } = state.configuration;
  const res = await util.request('POST', 'https://www.arcgis.com/sharing/rest/generateToken', {
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      username,
      password,
      referer: 'https://app.openfn.org',
      expiration: '60', // minutes
      f: 'json',
    }).toString(),
  });
  return { ...state, token: res.body.token };
});
